// Plain-language definitions for the harder terms in the "My views" questions,
// shown when a visitor hovers over, focuses or taps the underlined term.
//
// Wording stays neutral: where a term is contested, both sides' names for it are
// given, and nothing says which policy is better. `phrases` are matched in the
// question text, case-insensitively and on word boundaries; when two overlap, the
// longer phrase wins.

export const GLOSSARY = [
  // Economy, taxes, business
  { id: 'minimum-wage', phrases: ['minimum wage'], def: 'The lowest hourly pay employers may legally pay most workers. The federal minimum has been $7.25 since 2009; states and cities can set higher ones, and many do.' },
  { id: 'antitrust', phrases: ['antitrust laws'], def: 'Laws that keep markets competitive, for example by blocking mergers that would leave too few competitors, breaking up monopolies, and banning competitors from agreeing to fix prices.' },
  { id: 'monopoly', phrases: ['monopolies'], def: 'A monopoly is a company that controls all or nearly all of a market, so buyers have little choice and the company can largely set prices.' },
  { id: 'concentration', phrases: ['corporate concentration'], def: 'When a few large companies control most of an industry, such as meatpacking, airlines or internet search.' },
  { id: 'tax-incentives', phrases: ['tax incentives'], def: 'Tax breaks (lower rates, credits or deductions) offered to encourage something, such as building a factory or hiring workers in a particular place.' },
  { id: 'infrastructure', phrases: ['infrastructure'], def: 'The physical systems a country runs on: roads, bridges, railways, ports, airports, water pipes, power lines and internet networks.' },
  { id: 'national-debt', phrases: ['national debt'], def: 'The total the federal government owes from borrowing to cover past deficits, the years it spent more than it collected in taxes.' },
  { id: 'tax-credits', phrases: ['tax credits'], def: 'An amount subtracted directly from the tax someone owes. A deduction, by contrast, only lowers the income that gets taxed.' },
  { id: 'labor-protections', phrases: ['labor protections'], def: 'Laws covering workers’ pay, hours, overtime, safety and treatment on the job.' },
  { id: 'unionize', phrases: ['right to unionize'], def: 'Workers’ legal right to form a union and bargain with their employer as a group over pay, benefits and working conditions.' },
  { id: 'tariffs', phrases: ['tariffs'], def: 'Taxes on imported goods, paid by the importing business when the goods cross the border. Part of the cost is often passed on to buyers through higher prices.' },
  { id: 'family-leave', phrases: ['paid family leave'], def: 'Paid time off work to care for a new child or a seriously ill family member. Federal law guarantees some workers unpaid leave; paid leave depends on the employer or the state.' },
  { id: 'progressive-tax', phrases: ['progressive tax system'], def: 'A tax system where rates rise with income, so higher earners pay a larger share of their income. The federal income tax is progressive; a flat tax charges everyone the same rate.' },
  { id: 'work-week', phrases: ['working hours in a week'], def: 'The standard full-time week in the U.S. is 40 hours, with overtime pay required above that for many workers. Some propose a shorter week, such as 32 hours, at the same pay.' },

  // Healthcare
  { id: 'universal-coverage', phrases: ['universal healthcare coverage'], def: 'A system in which everyone has health insurance, whether through one government plan (single-payer), a mix of public and private plans, or a requirement to have coverage.' },
  { id: 'drug-negotiation', phrases: ['negotiate prescription drug prices'], def: 'Letting the government, through Medicare, bargain with drug makers over what it pays for medicines. The 2022 Inflation Reduction Act started this for a limited list of drugs.' },
  { id: 'public-insurance', phrases: ['public health insurance programs'], def: 'Government health coverage such as Medicare (mainly people 65 and older), Medicaid (people with low incomes) and CHIP (children in lower-income families).' },
  { id: 'private-system', phrases: ['private healthcare system'], def: 'A system where most people get health insurance from private companies, often through an employer, rather than from a government plan.' },
  { id: 'subsidies', phrases: ['subsidies'], def: 'Government payments or tax breaks that lower someone’s costs. In health care, premium tax credits help people who buy their own insurance; for farms, examples include crop insurance and price supports.' },
  { id: 'preexisting', phrases: ['preexisting conditions'], def: 'Health problems someone has before getting insurance, such as diabetes or cancer. Since 2014 the Affordable Care Act has barred insurers from refusing coverage or charging more because of them.' },
  { id: 'preventive-care', phrases: ['preventive care'], def: 'Care meant to prevent illness or catch it early, such as checkups, screenings and vaccines.' },
  { id: 'medicare', phrases: ['Medicare'], def: 'The federal health insurance program for people 65 and older and some younger people with disabilities. Traditional Medicare does not cover most dental, vision or hearing care.' },

  // Education
  { id: 'vocational', phrases: ['vocational'], def: 'Training for a specific trade or career, such as welding, electrical work, nursing or computer repair.' },
  { id: 'apprenticeship', phrases: ['apprenticeship'], def: 'A paid job in which a trainee learns a skilled trade on the job, usually alongside classroom instruction, for one to several years.' },
  { id: 'loan-forgiveness', phrases: ['student loan forgiveness'], def: 'Canceling some or all of what a borrower owes on student loans, so it no longer has to be repaid.' },
  { id: 'school-choice', phrases: ['school choice'], def: 'Policies that let families use public money or public options for a school other than their assigned public school, such as charter schools, vouchers or education savings accounts.' },
  { id: 'charter-schools', phrases: ['charter schools'], def: 'Public schools that are free to attend and paid for with tax money, but run independently of the local school district under a contract (a charter) and with fewer rules.' },
  { id: 'vouchers', phrases: ['school voucher programs'], def: 'Programs that give families public money to pay tuition at private schools, including religious schools.' },
  { id: 'curricula', phrases: ['school curricula'], def: 'What schools teach: the subjects, standards and materials. Local control means school boards and states decide this rather than the federal government.' },
  { id: 'school-meals', phrases: ['free school meals'], def: 'Students from lower-income families can already get free or reduced-price meals through federal programs. Free meals for all students would cover everyone regardless of income, as some states already do.' },
  { id: 'financial-literacy', phrases: ['financial literacy'], def: 'Knowing how to manage money: budgeting, saving, credit, loans and taxes.' },
  { id: 'civics', phrases: ['civics'], def: 'The study of how government works and of citizens’ rights and responsibilities.' },

  // Immigration
  { id: 'border-security', phrases: ['border security'], def: 'Measures to control who and what enters the country: Border Patrol agents, barriers and walls, surveillance technology, and inspections at ports of entry.' },
  { id: 'legal-status', phrases: ['pathway to legal status or citizenship'], def: 'A legal process letting certain immigrants who are in the U.S. without permission, such as people brought here as children, apply to stay lawfully and, in some proposals, eventually become citizens.' },
  { id: 'undocumented', phrases: ['undocumented immigrants'], def: 'People living in the U.S. without legal immigration status, because they entered without permission or stayed after a visa ran out.' },
  { id: 'skilled-workers', phrases: ['skilled workers'], def: 'Visas and green cards for workers with specialized skills or education, such as the H-1B visa for jobs like engineering and software development.' },
  { id: 'immigration-judges', phrases: ['immigration judges'], def: 'Judges in the Justice Department’s immigration courts who decide whether people may stay in the U.S. or must leave, including asylum claims.' },
  { id: 'backlogs', phrases: ['case backlogs'], def: 'The immigration courts have millions of pending cases, so many people wait years for a decision.' },
  { id: 'unauthorized-workers', phrases: ['unauthorized workers'], def: 'People working in the U.S. without legal permission to work.' },
  { id: 'refugees', phrases: ['refugees'], def: 'People who fled their home country because of persecution or war and are screened abroad before being resettled in the U.S. The president sets a yearly limit on how many are admitted.' },
  { id: 'deportation', phrases: ['deportation'], def: 'The government’s removal of a non-citizen from the United States, usually after an order from an immigration judge.' },
  { id: 'enforcement', phrases: ['immigration enforcement'], def: 'Finding, detaining and deporting people who are in the country without legal status. Inside the U.S. this is mainly the job of Immigration and Customs Enforcement (ICE).' },
  { id: 'work-visas', phrases: ['temporary work visas'], def: 'Permits to work in the U.S. for a limited time, such as H-2A visas for seasonal farm work and H-2B visas for other seasonal jobs.' },
  { id: 'e-verify', phrases: ['employment verification'], def: 'Checking that a new hire is allowed to work in the U.S., for example through E-Verify, a federal online system that compares a worker’s documents with government records.' },

  // Crime and safety
  { id: 'body-cameras', phrases: ['body cameras'], def: 'Small cameras worn by police officers that record their encounters with the public.' },
  { id: 'independent-investigations', phrases: ['independent investigations'], def: 'Reviews of alleged police misconduct done by people outside the department involved, such as a state agency, a prosecutor or a civilian review board.' },
  { id: 'rehabilitation', phrases: ['rehabilitation'], def: 'Programs that prepare prisoners to return to society without committing new crimes, such as education, job training, addiction treatment and counseling.' },
  { id: 'cash-bail', phrases: ['cash bail'], def: 'Money a person who has been arrested pays the court to be released before trial, returned if they show up for court. People who can’t pay may stay in jail while awaiting trial.' },
  { id: 'crime-prevention', phrases: ['community-based crime prevention'], def: 'Programs that work with neighborhoods to stop crime before it happens, such as violence interrupters, youth mentoring and job programs, better street lighting and neighborhood watch.' },
  { id: 'alternatives', phrases: ['alternatives to incarceration'], def: 'Ways to hold people accountable without jail or prison, such as drug courts, mental health courts, treatment programs, probation and community service.' },
  { id: 'death-penalty', phrases: ['death penalty'], def: 'Capital punishment: a sentence of execution, used for the most serious crimes such as murder. It is legal under federal law and in about half the states.' },
  { id: 'oversight', phrases: ['federal oversight of local law enforcement'], def: 'When a police department is found to have violated people’s civil rights, the U.S. Justice Department can sue and win a court-enforced agreement (a consent decree) requiring reforms, checked by a monitor.' },

  // Society
  { id: 'discrimination', phrases: ['protections against discrimination'], def: 'Laws that bar unfair treatment in jobs, housing, schools and public places because of traits such as race, sex, religion, disability, age or sexual orientation.' },
  { id: 'abortion-access', phrases: ['legal abortion access'], def: 'Whether and when abortion is legally available. Since the Supreme Court overturned Roe v. Wade in 2022 (the Dobbs decision), each state sets its own rules, from bans with few exceptions to few or no limits.' },
  { id: 'abortion-restrictions', phrases: ['restrictions on abortion'], def: 'Limits such as bans after a set number of weeks, waiting periods, or rules on abortion pills. Since 2022 most of these are set by each state.' },
  { id: 'marijuana', phrases: ['recreational marijuana'], def: 'Marijuana for personal use by adults, not only for medical reasons. It is legal in about half the states but still illegal under federal law.' },
  { id: 'personal-data', phrases: ['personal data'], def: 'Information about people that apps and websites collect, such as location, browsing and purchases. The U.S. has no general federal privacy law, so rules on collecting, selling and deleting it vary by state.' },
  { id: 'end-of-life', phrases: ['end-of-life medical decisions'], def: 'Lets a terminally ill adult with a short time to live get a prescription to end their life, under safeguards like doctors’ approval and waiting periods. Supporters call it medical aid in dying; opponents call it assisted suicide. Legal in about a dozen states.' },
  { id: 'same-sex-marriage', phrases: ['same-sex marriage'], def: 'Marriage between two people of the same sex, legal nationwide since the Supreme Court’s 2015 Obergefell decision. The 2022 Respect for Marriage Act requires federal and state recognition of these marriages.' },
  { id: 'hormone-transitioning', phrases: ['hormone transitioning'], def: 'Medical treatment for transgender minors using puberty blockers or hormones so their bodies develop in line with their gender identity. About half the states restrict or ban it for people under 18.' },
  { id: 'trans-rights', phrases: ['trans rights'], def: 'Laws and policies for transgender people, whose gender identity differs from the sex recorded at birth, covering areas such as discrimination, sports teams, bathrooms, ID documents and health care.' },

  // Energy and environment
  { id: 'renewable', phrases: ['renewable energy'], def: 'Energy from sources that don’t run out, such as sunlight, wind, flowing water (hydropower) and heat from underground (geothermal).' },
  { id: 'nuclear', phrases: ['nuclear power'], def: 'Electricity from power plants that split uranium atoms. The plants release no carbon dioxide while running but leave radioactive waste that must be stored safely.' },
  { id: 'ev-infrastructure', phrases: ['electric vehicle infrastructure'], def: 'Charging stations for electric cars and trucks, and the power-grid upgrades needed to supply them.' },
  { id: 'carbon-limits', phrases: ['carbon emissions limits'], def: 'Caps on how much carbon dioxide, the main gas warming the climate, power plants, factories and other large sources may release, set by regulations or by cap-and-trade programs.' },
  { id: 'passenger-rail', phrases: ['passenger rail'], def: 'Trains that carry people rather than freight, such as Amtrak between cities and commuter lines into big cities.' },
  { id: 'public-transportation', phrases: ['public transportation'], def: 'Buses, subways, light rail and other shared transit open to everyone.' },
  { id: 'energy-manufacturing', phrases: ['domestic energy manufacturing'], def: 'Making energy equipment in the U.S., such as solar panels, wind turbines, batteries and nuclear fuel.' },
  { id: 'lower-emission', phrases: ['lower-emission energy sources'], def: 'Energy that releases less carbon dioxide than coal, oil and gas, such as wind, solar, hydropower and nuclear.' },

  // Defense and foreign policy
  { id: 'alliances', phrases: ['military alliances'], def: 'Treaties in which countries promise to defend each other, such as NATO (the U.S., Canada and 30 European countries) and U.S. defense treaties with Japan and South Korea.' },
  { id: 'war-powers', phrases: ['congressional authorization'], def: 'The Constitution gives Congress the power to declare war. The 1973 War Powers Resolution says troops sent into hostilities must leave within 60 days, plus 30 to withdraw, unless Congress approves. Presidents of both parties have often acted without a vote.' },
  { id: 'military-assistance', phrases: ['military assistance'], def: 'Weapons, equipment, training or money given to another country’s armed forces.' },
  { id: 'diplomacy', phrases: ['diplomacy'], def: 'Handling disputes with other countries through talks, negotiations, treaties and sanctions rather than military force.' },
  { id: 'intervention', phrases: ['intervention'], def: 'Military action in or against another country, such as air strikes or sending troops, as opposed to relying on diplomacy or sanctions alone.' },
  { id: 'presence-overseas', phrases: ['military presence overseas'], def: 'U.S. troops, ships and bases stationed abroad, in places such as Japan, Germany and South Korea, to deter attacks and support allies.' },
  { id: 'cybersecurity', phrases: ['cybersecurity'], def: 'Protecting computers and networks from hacking, theft and sabotage.' },
  { id: 'critical-infrastructure', phrases: ['critical-infrastructure'], def: 'Systems society can’t run without, such as power grids, water treatment, hospitals, banks, pipelines and communications networks.' },
  { id: 'foreign-aid', phrases: ['foreign aid'], def: 'Money, goods and services the U.S. gives other countries, for disaster relief, health programs, economic development and security.' },
  { id: 'hostile-state', phrases: ['hostile state'], def: 'A country whose government works against another country’s interests or security, for example through military aggression, hacking or interfering in elections.' },
  { id: 'eu', phrases: ['European Union'], def: 'A political and economic union of 27 European countries with a shared market, common trade rules and, for most members, a shared currency, the euro.' },

  // Government and elections
  { id: 'term-limits', phrases: ['term limits'], def: 'A cap on how many terms someone may serve in an office. Presidents are limited to two terms; members of Congress have no limit, and adding one would take a constitutional amendment.' },
  { id: 'stock-trading', phrases: ['trading individual stocks'], def: 'Buying and selling shares of particular companies. Supporters of a ban say lawmakers could profit from information they learn on the job; opponents say requiring prompt public reports of every trade is enough.' },
  { id: 'disclosure', phrases: ['campaign finance disclosure'], def: 'Rules requiring campaigns and political groups to report who gives them money and how they spend it.' },
  { id: 'redistricting', phrases: ['congressional district boundaries'], def: 'District lines are redrawn every 10 years after the census. In most states the legislature draws them, which lets the party in power shape districts to its own advantage, called gerrymandering. An independent commission gives the job to a panel of citizens instead of lawmakers.' },
  { id: 'voter-id', phrases: ['voter identification'], def: 'Requiring voters to show identification, such as a driver’s license, before voting. Rules vary by state: some require a photo ID, others accept other documents, and some ask for none.' },
  { id: 'early-voting', phrases: ['early voting'], def: 'Voting in person before Election Day, at set locations and times. How many days are offered varies by state.' },
  { id: 'mail-ballots', phrases: ['mail-in ballots'], def: 'Ballots sent to voters and returned by mail or drop box. Some states mail one to every voter; others require an application or a reason.' },
  { id: 'rcv', phrases: ['ranked-choice voting'], def: 'Voters rank candidates in order of preference. If no one wins a majority of first choices, the last-place candidate is eliminated and those ballots go to each voter’s next choice, repeating until someone has a majority. Maine and Alaska use it for some or all statewide elections.' },
  { id: 'electoral-college', phrases: ['Electoral College'], def: 'How the president is chosen: each state gets electors equal to its senators plus representatives, 538 in all, and a candidate needs 270. Most states give all their electors to the statewide winner, so a candidate can win while losing the national popular vote.' },
  { id: 'ballot-initiatives', phrases: ['ballot initiatives'], def: 'A process letting citizens put a proposed law or constitutional amendment on the ballot by gathering enough voter signatures. About half the states allow it.' },
  { id: 'corporate-donations', phrases: ['corporate political donations', 'finance campaigns'], def: 'Corporations can’t give money directly to federal candidates, but since the Supreme Court’s 2010 Citizens United decision they may spend unlimited sums on political ads through independent groups such as super PACs.' },

  // Housing and infrastructure
  { id: 'affordable-housing', phrases: ['affordable housing'], def: 'Housing that costs a household no more than about 30% of its income. Government programs such as the Low-Income Housing Tax Credit help build homes with limited rents.' },
  { id: 'corporate-housing', phrases: ['corporate investment into housing'], def: 'Large investment firms buying many single-family homes, usually to rent them out.' },
  { id: 'zoning', phrases: ['zoning reforms'], def: 'Zoning is the local rules on what may be built where, for example only single-family houses. Reforms allow more homes, such as duplexes, apartments or houses on smaller lots.' },
  { id: 'eviction', phrases: ['unfair eviction'], def: 'An eviction is the legal removal of a renter from a home. Tenant protections can require a valid reason, advance notice or a right to a lawyer.' },
  { id: 'broadband', phrases: ['broadband'], def: 'High-speed internet service. Many rural areas lack it because running cable to far-apart homes is expensive.' },
  { id: 'ppp', phrases: ['public-private partnerships'], def: 'Deals in which government and private companies share the cost, risk and sometimes the revenue, such as tolls, of building and running projects like roads and bridges.' },

  // Agriculture and industry
  { id: 'semiconductors', phrases: ['semiconductor'], def: 'Semiconductors are computer chips, the tiny electronic parts inside phones, cars, appliances and weapons. Most of the most advanced chips are made in Taiwan; the 2022 CHIPS Act pays for new chip factories in the U.S.' },
  { id: 'pharmaceutical', phrases: ['pharmaceutical production'], def: 'Making medicines and their ingredients. Many generic drugs and drug ingredients used in the U.S. come from China and India.' },
  { id: 'supply-chains', phrases: ['supply chains'], def: 'The network of suppliers and steps that turn raw materials into finished products and deliver them.' },
  { id: 'critical-minerals', phrases: ['critical minerals'], def: 'Minerals essential to modern technology and defense whose supply is at risk, such as lithium, cobalt and rare earth elements used in batteries, electronics and weapons. China dominates much of their processing.' },
  { id: 'trade-agreements', phrases: ['trade agreements'], def: 'Deals between countries to lower tariffs and other trade barriers, such as the USMCA between the U.S., Mexico and Canada.' },
  { id: 'protectionism', phrases: ['protecting domestic industries'], def: 'Shielding a country’s businesses from foreign competition with tariffs, import limits or subsidies. It can protect jobs in those industries but usually raises prices for buyers.' },
  { id: 'drought-resistant', phrases: ['drought-resistant crop'], def: 'Crop varieties bred or engineered to need less water and survive dry spells.' },

  // State and local
  { id: 'property-tax', phrases: ['property tax relief'], def: 'Lowering the tax homeowners pay on the value of their property, through rate cuts, exemptions or caps on yearly increases. Property taxes mainly fund schools and local services.' },
  { id: 'coastal-restoration', phrases: ['coastal restoration'], def: 'Rebuilding wetlands, barrier islands and shorelines that shield coastal communities from storm surge and erosion.' },
  { id: 'technical-colleges', phrases: ['technical colleges'], def: 'Two-year public colleges that teach job skills such as welding, nursing, auto repair and computer support.' },
  { id: 'tax-exemptions', phrases: ['tax exemptions'], def: 'Breaks that let some businesses, groups or property pay less tax or none, often to attract jobs or support charities.' },
];

// French phrases and definitions (Nov. 25, 2026), matched in the French questions;
// the English above stays as written. Same rules: neutral, nothing that can go stale.
const FR = {
  'minimum-wage': [['salaire minimum'], 'Le salaire horaire le plus bas que les employeurs peuvent légalement verser à la plupart des salariés. Le minimum fédéral est de 7,25 dollars depuis 2009 ; les États et les villes peuvent en fixer un plus élevé, et beaucoup le font.'],
  'antitrust': [['lois antitrust'], 'Des lois qui préservent la concurrence, par exemple en bloquant les fusions qui laisseraient trop peu de concurrents, en démantelant les monopoles et en interdisant aux concurrents de s’entendre sur les prix.'],
  'monopoly': [['monopoles'], 'Un monopole est une entreprise qui contrôle tout ou presque tout un marché : les acheteurs ont peu de choix et elle peut largement fixer les prix.'],
  'concentration': [['concentration excessive des entreprises'], 'Quand quelques grandes entreprises contrôlent l’essentiel d’un secteur, comme la transformation de la viande, le transport aérien ou la recherche sur internet.'],
  'tax-incentives': [['avantages fiscaux'], 'Des allègements d’impôt (taux réduits, crédits ou déductions) accordés pour encourager quelque chose, comme construire une usine ou embaucher dans un endroit donné.'],
  'infrastructure': [['infrastructures', 'infrastructure'], 'Les équipements physiques dont dépend un pays : routes, ponts, voies ferrées, ports, aéroports, canalisations d’eau, lignes électriques et réseaux internet.'],
  'national-debt': [['dette nationale'], 'Le total que doit l’État fédéral pour avoir emprunté afin de couvrir ses déficits passés, les années où il a dépensé plus qu’il n’a perçu d’impôts.'],
  'tax-credits': [['crédits d’impôt'], 'Un montant retranché directement de l’impôt dû. Une déduction, à l’inverse, réduit seulement le revenu imposable.'],
  'labor-protections': [['protection des travailleurs'], 'Les lois sur le salaire, la durée du travail, les heures supplémentaires, la sécurité et le traitement des salariés au travail.'],
  'unionize': [['droit de se syndiquer'], 'Le droit des salariés de former un syndicat et de négocier collectivement avec leur employeur les salaires, les avantages et les conditions de travail.'],
  'tariffs': [['droits de douane'], 'Des taxes sur les produits importés, payées par l’entreprise importatrice quand les marchandises passent la frontière. Une partie du coût est souvent répercutée sur les acheteurs par des prix plus élevés.'],
  'family-leave': [['congé familial payé'], 'Un congé rémunéré pour s’occuper d’un nouvel enfant ou d’un proche gravement malade. La loi fédérale garantit à certains salariés un congé non payé ; le congé payé dépend de l’employeur ou de l’État.'],
  'progressive-tax': [['système fiscal plus progressif'], 'Un système où les taux augmentent avec le revenu, si bien que les plus hauts revenus paient une plus grande part de leurs revenus. L’impôt fédéral sur le revenu est progressif ; un impôt à taux unique (flat tax) applique le même taux à tous.'],
  'work-week': [['heures de travail par semaine'], 'La semaine normale de travail à temps plein aux États-Unis est de 40 heures, avec des heures supplémentaires majorées au-delà pour beaucoup de salariés. Certains proposent une semaine plus courte, par exemple de 32 heures, sans baisse de salaire.'],
  'universal-coverage': [['couverture santé universelle'], 'Un système où tout le monde a une assurance maladie, que ce soit par un régime public unique (payeur unique), un mélange de régimes publics et privés ou une obligation d’être assuré.'],
  'drug-negotiation': [['négocier le prix des médicaments sur ordonnance'], 'Permettre à l’État, par l’intermédiaire de Medicare, de négocier avec les laboratoires le prix qu’il paie pour les médicaments. L’Inflation Reduction Act de 2022 l’a mis en place pour une liste limitée de médicaments.'],
  'public-insurance': [['programmes publics d’assurance maladie'], 'La couverture santé publique, comme Medicare (surtout les personnes de 65 ans et plus), Medicaid (les personnes à faibles revenus) et CHIP (les enfants des familles modestes).'],
  'private-system': [['système de santé principalement privé'], 'Un système où la plupart des gens sont assurés par des compagnies privées, souvent par leur employeur, plutôt que par un régime public.'],
  'subsidies': [['aides publiques', 'subventions'], 'Des versements ou des allègements d’impôt de l’État qui réduisent les coûts de quelqu’un. En santé, des crédits d’impôt sur les primes aident ceux qui s’assurent eux-mêmes ; pour l’agriculture, l’assurance récolte et le soutien des prix en sont des exemples.'],
  'preexisting': [['maladies préexistantes'], 'Les problèmes de santé qu’une personne a avant de s’assurer, comme le diabète ou un cancer. Depuis 2014, l’Affordable Care Act interdit aux assureurs de refuser de la couvrir ou de lui faire payer plus pour cette raison.'],
  'preventive-care': [['soins de prévention'], 'Les soins destinés à prévenir les maladies ou à les détecter tôt, comme les bilans de santé, les dépistages et les vaccins.'],
  'medicare': [['Medicare'], 'Le programme fédéral d’assurance maladie des personnes de 65 ans et plus et de certaines personnes handicapées plus jeunes. Le Medicare classique ne couvre pas la plupart des soins dentaires, ophtalmologiques ou auditifs.'],
  'vocational': [['formation professionnelle'], 'Une formation à un métier précis, comme la soudure, l’électricité, les soins infirmiers ou la réparation informatique.'],
  'apprenticeship': [['apprentissage'], 'Un emploi rémunéré où l’apprenti apprend un métier qualifié sur le terrain, en général avec des cours, pendant un à plusieurs ans.'],
  'loan-forgiveness': [['annulation des prêts étudiants'], 'L’effacement d’une partie ou de la totalité de ce qu’un emprunteur doit sur ses prêts étudiants, qui n’ont alors plus à être remboursés.'],
  'school-choice': [['libre choix de l’école'], 'Des politiques qui permettent aux familles d’utiliser de l’argent public ou des options publiques pour une autre école que l’école publique de leur secteur, comme les écoles à charte, les chèques éducation ou les comptes d’épargne éducation.'],
  'charter-schools': [['écoles à charte'], 'Des écoles publiques gratuites, financées par l’impôt, mais gérées indépendamment du district scolaire local dans le cadre d’un contrat (une charte), avec moins de règles.'],
  'vouchers': [['chèques éducation'], 'Des programmes qui donnent aux familles de l’argent public pour payer les frais de scolarité d’écoles privées, y compris religieuses.'],
  'curricula': [['programmes scolaires'], 'Ce que les écoles enseignent : les matières, les normes et les supports. Le contrôle local signifie que les conseils scolaires et les États en décident plutôt que l’État fédéral.'],
  'school-meals': [['gratuité des repas scolaires'], 'Les élèves des familles modestes peuvent déjà avoir des repas gratuits ou à prix réduit grâce à des programmes fédéraux. Des repas gratuits pour tous couvriraient chaque élève quel que soit le revenu, comme certains États le font déjà.'],
  'financial-literacy': [['éducation financière'], 'Savoir gérer son argent : budget, épargne, crédit, emprunts et impôts.'],
  'civics': [['éducation civique'], 'L’étude du fonctionnement des institutions et des droits et devoirs des citoyens.'],
  'border-security': [['sécurité aux frontières'], 'Les mesures pour contrôler qui et quoi entre dans le pays : agents de la police des frontières (Border Patrol), barrières et murs, technologies de surveillance et contrôles aux points d’entrée.'],
  'legal-status': [['voie d’accès à un statut légal ou à la citoyenneté'], 'Une procédure légale permettant à certains immigrés présents aux États-Unis sans autorisation, comme ceux arrivés enfants, de demander à rester légalement et, selon certaines propositions, de devenir un jour citoyens.'],
  'undocumented': [['immigrés sans papiers'], 'Les personnes qui vivent aux États-Unis sans statut d’immigration légal, parce qu’elles sont entrées sans autorisation ou sont restées après l’expiration de leur visa.'],
  'skilled-workers': [['travailleurs qualifiés'], 'Les visas et cartes vertes pour les travailleurs ayant des compétences ou des diplômes spécialisés, comme le visa H-1B pour des métiers comme l’ingénierie ou le développement de logiciels.'],
  'immigration-judges': [['juges de l’immigration'], 'Les juges des tribunaux de l’immigration du ministère de la Justice, qui décident si une personne peut rester aux États-Unis ou doit partir, y compris sur les demandes d’asile.'],
  'backlogs': [['dossiers en attente'], 'Les tribunaux de l’immigration ont des millions d’affaires en attente, si bien que beaucoup de gens attendent une décision pendant des années.'],
  'unauthorized-workers': [['travailleurs sans autorisation de travail'], 'Les personnes qui travaillent aux États-Unis sans autorisation légale de travailler.'],
  'refugees': [['réfugiés'], 'Les personnes qui ont fui leur pays à cause de persécutions ou d’une guerre et dont le dossier est examiné à l’étranger avant leur réinstallation aux États-Unis. Le président fixe chaque année un plafond d’admissions.'],
  'deportation': [['expulsion'], 'Le renvoi par l’État d’une personne non citoyenne hors des États-Unis, en général après une décision d’un juge de l’immigration.'],
  'enforcement': [['application des lois sur l’immigration'], 'Rechercher, détenir et expulser les personnes présentes dans le pays sans statut légal. À l’intérieur des États-Unis, c’est surtout le rôle de l’ICE (Immigration and Customs Enforcement).'],
  'work-visas': [['visas de travail temporaires'], 'Des permis de travailler aux États-Unis pour une durée limitée, comme les visas H-2A pour le travail agricole saisonnier et H-2B pour les autres emplois saisonniers.'],
  'e-verify': [['vérification renforcée du droit au travail'], 'Vérifier qu’une nouvelle recrue a le droit de travailler aux États-Unis, par exemple avec E-Verify, un système fédéral en ligne qui compare les papiers du salarié aux fichiers de l’administration.'],
  'body-cameras': [['caméras-piétons'], 'De petites caméras portées par les policiers, qui enregistrent leurs interventions auprès du public.'],
  'independent-investigations': [['enquêtes indépendantes'], 'Des examens des fautes policières présumées menés par des personnes extérieures au service concerné, comme une agence de l’État, un procureur ou une commission de citoyens.'],
  'rehabilitation': [['réinsertion'], 'Les programmes qui préparent les détenus à revenir dans la société sans commettre de nouveaux délits : enseignement, formation professionnelle, traitement des addictions et accompagnement psychologique.'],
  'cash-bail': [['caution en argent'], 'La somme qu’une personne arrêtée verse au tribunal pour être libérée avant son procès, rendue si elle se présente aux audiences. Ceux qui ne peuvent pas payer peuvent rester en prison en attendant leur procès.'],
  'crime-prevention': [['prévention de la délinquance de proximité'], 'Des programmes menés avec les quartiers pour empêcher la délinquance avant qu’elle ne se produise : médiateurs contre la violence, tutorat de jeunes et programmes d’emploi, meilleur éclairage des rues, vigilance entre voisins.'],
  'alternatives': [['alternatives à l’incarcération'], 'Des moyens de sanctionner sans prison, comme les tribunaux spécialisés en drogue ou en santé mentale, les programmes de soins, la probation et les travaux d’intérêt général.'],
  'death-penalty': [['peine de mort'], 'La peine capitale : une condamnation à l’exécution, pour les crimes les plus graves comme le meurtre. Elle est légale en droit fédéral et dans environ la moitié des États.'],
  'oversight': [['contrôle fédéral renforcé sur les polices locales'], 'Quand un service de police a violé les droits civiques de la population, le ministère fédéral de la Justice peut le poursuivre et obtenir un accord sous le contrôle d’un juge (consent decree) qui impose des réformes, vérifiées par un observateur.'],
  'discrimination': [['discriminations'], 'Les lois qui interdisent les traitements injustes dans l’emploi, le logement, l’école et les lieux publics en raison de caractéristiques comme l’origine, le sexe, la religion, le handicap, l’âge ou l’orientation sexuelle.'],
  'abortion-access': [['accès légal à l’avortement'], 'Si et quand l’avortement est légalement possible. Depuis que la Cour suprême a annulé l’arrêt Roe v. Wade en 2022 (la décision Dobbs), chaque État fixe ses propres règles, de l’interdiction avec peu d’exceptions à peu ou pas de limites.'],
  'abortion-restrictions': [['restrictions plus fortes sur l’avortement'], 'Des limites comme l’interdiction au-delà d’un certain nombre de semaines, des délais d’attente ou des règles sur la pilule abortive. Depuis 2022, la plupart sont fixées par chaque État.'],
  'marijuana': [['cannabis récréatif'], 'Le cannabis à usage personnel pour les adultes, pas seulement à des fins médicales. Il est légal dans environ la moitié des États mais reste illégal en droit fédéral.'],
  'personal-data': [['données personnelles'], 'Les informations sur les personnes que collectent les applications et les sites, comme la localisation, la navigation et les achats. Les États-Unis n’ont pas de loi fédérale générale sur la vie privée, si bien que les règles de collecte, de vente et de suppression varient selon les États.'],
  'end-of-life': [['décisions médicales de fin de vie'], 'Permet à un adulte en phase terminale, à qui il reste peu de temps à vivre, d’obtenir une prescription pour mettre fin à ses jours, avec des garanties comme l’accord de médecins et des délais d’attente. Ses partisans parlent d’aide médicale à mourir ; ses opposants, de suicide assisté. Légal dans une dizaine d’États.'],
  'same-sex-marriage': [['mariage entre personnes de même sexe'], 'Le mariage entre deux personnes du même sexe, légal dans tout le pays depuis la décision Obergefell de la Cour suprême en 2015. Le Respect for Marriage Act de 2022 impose à l’État fédéral et aux États de reconnaître ces mariages.'],
  'hormone-transitioning': [['transition hormonale'], 'Un traitement médical des mineurs transgenres par des bloqueurs de puberté ou des hormones, pour que leur corps se développe en accord avec leur identité de genre. Environ la moitié des États le restreignent ou l’interdisent avant 18 ans.'],
  'trans-rights': [['droits des personnes trans'], 'Les lois et les politiques concernant les personnes transgenres, dont l’identité de genre diffère du sexe enregistré à la naissance, dans des domaines comme les discriminations, les équipes sportives, les toilettes, les papiers d’identité et la santé.'],
  'renewable': [['énergies renouvelables'], 'L’énergie tirée de sources qui ne s’épuisent pas, comme le soleil, le vent, l’eau courante (hydroélectricité) et la chaleur du sous-sol (géothermie).'],
  'nuclear': [['énergie nucléaire'], 'L’électricité produite par des centrales qui fissionnent des atomes d’uranium. Elles ne rejettent pas de dioxyde de carbone en fonctionnement mais laissent des déchets radioactifs à stocker en sécurité.'],
  'ev-infrastructure': [['infrastructures pour véhicules électriques'], 'Les bornes de recharge pour voitures et camions électriques, et les renforcements du réseau électrique nécessaires pour les alimenter.'],
  'carbon-limits': [['plafonds d’émissions de carbone'], 'Des plafonds sur la quantité de dioxyde de carbone, principal gaz qui réchauffe le climat, que les centrales, les usines et les autres grandes sources peuvent rejeter, fixés par la réglementation ou par des marchés de quotas.'],
  'passenger-rail': [['trains de voyageurs'], 'Les trains qui transportent des personnes plutôt que des marchandises, comme Amtrak entre les villes et les lignes de banlieue vers les grandes villes.'],
  'public-transportation': [['transports en commun'], 'Les bus, métros, tramways et autres transports partagés ouverts à tous.'],
  'energy-manufacturing': [['fabrication d’équipements énergétiques'], 'La fabrication aux États-Unis d’équipements énergétiques, comme les panneaux solaires, les éoliennes, les batteries et le combustible nucléaire.'],
  'lower-emission': [['sources d’énergie moins émettrices'], 'Les énergies qui rejettent moins de dioxyde de carbone que le charbon, le pétrole et le gaz, comme l’éolien, le solaire, l’hydroélectricité et le nucléaire.'],
  'alliances': [['alliances militaires'], 'Des traités par lesquels des pays promettent de se défendre mutuellement, comme l’OTAN (les États-Unis, le Canada et 30 pays européens) et les traités de défense des États-Unis avec le Japon et la Corée du Sud.'],
  'war-powers': [['autorisation du Congrès'], 'La Constitution donne au Congrès le pouvoir de déclarer la guerre. La War Powers Resolution de 1973 prévoit que des troupes engagées dans des hostilités doivent se retirer sous 60 jours, plus 30 pour le retrait, sauf accord du Congrès. Des présidents des deux partis ont souvent agi sans vote.'],
  'military-assistance': [['aide militaire'], 'Les armes, équipements, formations ou fonds donnés aux forces armées d’un autre pays.'],
  'diplomacy': [['diplomatie'], 'Régler les différends avec d’autres pays par le dialogue, les négociations, les traités et les sanctions plutôt que par la force militaire.'],
  'intervention': [['intervention militaire', 'intervention'], 'Une action militaire dans un autre pays ou contre lui, comme des frappes aériennes ou l’envoi de troupes, plutôt que de s’en tenir à la diplomatie ou aux sanctions.'],
  'presence-overseas': [['présence militaire américaine à l’étranger'], 'Les troupes, navires et bases des États-Unis stationnés à l’étranger, par exemple au Japon, en Allemagne et en Corée du Sud, pour dissuader les attaques et soutenir les alliés.'],
  'cybersecurity': [['cybersécurité'], 'La protection des ordinateurs et des réseaux contre le piratage, le vol et le sabotage.'],
  'critical-infrastructure': [['infrastructures critiques'], 'Les systèmes sans lesquels la société ne peut pas fonctionner, comme les réseaux électriques, le traitement de l’eau, les hôpitaux, les banques, les oléoducs et gazoducs et les réseaux de communication.'],
  'foreign-aid': [['aide à l’étranger'], 'L’argent, les biens et les services que les États-Unis donnent à d’autres pays, pour l’aide d’urgence, la santé, le développement économique et la sécurité.'],
  'hostile-state': [['État hostile'], 'Un pays dont le gouvernement agit contre les intérêts ou la sécurité d’un autre pays, par exemple par une agression militaire, du piratage ou de l’ingérence électorale.'],
  'eu': [['Union européenne'], 'Une union politique et économique de 27 pays européens, avec un marché commun, des règles commerciales communes et, pour la plupart de ses membres, une monnaie commune, l’euro.'],
  'term-limits': [['limitation du nombre de mandats'], 'Un plafond sur le nombre de mandats qu’une personne peut exercer à un poste. Les présidents sont limités à deux mandats ; les membres du Congrès n’ont pas de limite, et en instaurer une exigerait un amendement à la Constitution.'],
  'stock-trading': [['actions individuelles'], 'Acheter et vendre des actions de sociétés précises. Les partisans d’une interdiction disent que les élus pourraient profiter d’informations apprises dans leurs fonctions ; ses opposants estiment qu’une déclaration publique rapide de chaque opération suffit.'],
  'disclosure': [['transparence sur le financement des campagnes'], 'Les règles qui obligent les campagnes et les groupes politiques à déclarer qui leur donne de l’argent et comment ils le dépensent.'],
  'redistricting': [['circonscriptions du Congrès'], 'Les limites des circonscriptions sont redessinées tous les 10 ans après le recensement. Dans la plupart des États, c’est le parlement de l’État qui les trace, ce qui permet au parti au pouvoir de les dessiner à son avantage (le gerrymandering). Une commission indépendante confie ce travail à un groupe de citoyens plutôt qu’aux élus.'],
  'voter-id': [['pièce d’identité'], 'Exiger des électeurs qu’ils présentent une pièce d’identité, comme un permis de conduire, avant de voter. Les règles varient selon les États : certains exigent une pièce avec photo, d’autres acceptent d’autres documents, et certains n’en demandent aucune.'],
  'early-voting': [['vote anticipé'], 'Voter en personne avant le jour de l’élection, dans des lieux et à des horaires fixés. Le nombre de jours proposés varie selon les États.'],
  'mail-ballots': [['vote par correspondance'], 'Des bulletins envoyés aux électeurs et renvoyés par la poste ou déposés dans une urne. Certains États en envoient un à chaque électeur ; d’autres exigent une demande ou un motif.'],
  'rcv': [['vote par classement'], 'Les électeurs classent les candidats par ordre de préférence. Si personne n’obtient la majorité des premiers choix, le dernier est éliminé et ses bulletins vont au choix suivant de chaque électeur, jusqu’à ce qu’un candidat ait la majorité. Le Maine et l’Alaska l’utilisent pour tout ou partie de leurs élections à l’échelle de l’État.'],
  'electoral-college': [['collège électoral'], 'Le mode de désignation du président : chaque État a autant de grands électeurs que de sénateurs et de représentants, 538 en tout, et il en faut 270 pour gagner. La plupart des États donnent tous leurs grands électeurs au vainqueur dans l’État, si bien qu’un candidat peut gagner en perdant le vote populaire national.'],
  'ballot-initiatives': [['initiatives populaires'], 'Une procédure qui permet aux citoyens de soumettre au vote une proposition de loi ou d’amendement constitutionnel en réunissant assez de signatures d’électeurs. Environ la moitié des États la permettent.'],
  'corporate-donations': [['dons politiques des entreprises', 'financer les campagnes électorales'], 'Les entreprises ne peuvent pas donner directement aux candidats fédéraux, mais depuis la décision Citizens United de la Cour suprême en 2010, elles peuvent dépenser sans limite en publicités politiques par l’intermédiaire de groupes indépendants comme les super PAC.'],
  'affordable-housing': [['logements abordables'], 'Un logement qui ne coûte pas plus d’environ 30 % des revenus d’un ménage. Des programmes publics comme le Low-Income Housing Tax Credit aident à construire des logements aux loyers plafonnés.'],
  'corporate-housing': [['investissements des entreprises dans le logement'], 'De grandes sociétés d’investissement qui achètent de nombreuses maisons individuelles, en général pour les louer.'],
  'zoning': [['réformes du zonage'], 'Le zonage, ce sont les règles locales sur ce qui peut être construit et où, par exemple uniquement des maisons individuelles. Les réformes permettent plus de logements, comme des maisons à deux logements, des immeubles ou des maisons sur de plus petits terrains.'],
  'eviction': [['expulsions abusives'], 'Une expulsion est le départ forcé, par voie légale, d’un locataire de son logement. La protection des locataires peut exiger un motif valable, un préavis ou le droit à un avocat.'],
  'broadband': [['internet haut débit'], 'Un accès internet à haut débit. Beaucoup de zones rurales n’en ont pas, parce qu’il coûte cher de tirer des câbles jusqu’à des maisons éloignées les unes des autres.'],
  'ppp': [['partenariats public-privé'], 'Des accords où l’État et des entreprises privées partagent le coût, le risque et parfois les recettes, comme les péages, de la construction et de l’exploitation de projets comme les routes et les ponts.'],
  'semiconductors': [['semi-conducteurs'], 'Les semi-conducteurs sont les puces électroniques, ces minuscules composants présents dans les téléphones, les voitures, l’électroménager et les armes. La plupart des puces les plus avancées sont fabriquées à Taïwan ; le CHIPS Act de 2022 finance de nouvelles usines de puces aux États-Unis.'],
  'pharmaceutical': [['production pharmaceutique'], 'La fabrication des médicaments et de leurs principes actifs. Beaucoup de médicaments génériques et de principes actifs utilisés aux États-Unis viennent de Chine et d’Inde.'],
  'supply-chains': [['chaînes d’approvisionnement'], 'Le réseau de fournisseurs et d’étapes qui transforment des matières premières en produits finis et les livrent.'],
  'critical-minerals': [['minerais critiques'], 'Des minerais indispensables aux technologies modernes et à la défense dont l’approvisionnement est menacé, comme le lithium, le cobalt et les terres rares utilisés dans les batteries, l’électronique et les armes. La Chine domine une grande partie de leur transformation.'],
  'trade-agreements': [['accords commerciaux'], 'Des accords entre pays pour réduire les droits de douane et les autres obstacles au commerce, comme l’ACEUM (USMCA en anglais) entre les États-Unis, le Mexique et le Canada.'],
  'protectionism': [['protection de l’industrie nationale'], 'Protéger les entreprises d’un pays de la concurrence étrangère par des droits de douane, des limites aux importations ou des subventions. Cela peut préserver des emplois dans ces secteurs mais fait en général monter les prix pour les acheteurs.'],
  'drought-resistant': [['cultures résistantes à la sécheresse'], 'Des variétés de plantes sélectionnées ou modifiées pour avoir besoin de moins d’eau et survivre aux périodes sèches.'],
  'property-tax': [['allègement de la taxe foncière'], 'Réduire l’impôt que paient les propriétaires sur la valeur de leur bien, par des baisses de taux, des exonérations ou des plafonds sur les hausses annuelles. La taxe foncière finance surtout les écoles et les services locaux.'],
  'coastal-restoration': [['restauration du littoral'], 'La reconstitution des zones humides, des îles-barrières et des rivages qui protègent les communautés côtières des ondes de tempête et de l’érosion.'],
  'technical-colleges': [['écoles techniques'], 'Des établissements publics en deux ans qui enseignent des compétences professionnelles, comme la soudure, les soins infirmiers, la réparation automobile et l’assistance informatique.'],
  'tax-exemptions': [['exonérations fiscales'], 'Des allègements qui permettent à certaines entreprises, associations ou propriétés de payer moins d’impôt ou pas du tout, souvent pour attirer des emplois ou soutenir des œuvres caritatives.'],
};
for (const g of GLOSSARY) [g.phrasesFr, g.defFr] = FR[g.id] || [[], g.def];
